			"title": "KONOSUBA -God's blessing on this wonderful world!",
			"romaji": "Kono Subarashii Sekai ni Shukufuku wo!",
			"native": "この素晴らしい世界に祝福を！",
			"synopsis": "Kazuma Satou decides that today is the day to get out of the house for a bit. Since he dies, pointlessly, it's clearly a bad choice. The goddess who greets him in the afterlife, however, offers him a chance to be reborn in a world not unlike that of a video game, and as a bonus she'll even throw in a cool item or power! Can't possibly be a bad choice, right? Except he arrives with no money at all, dead average skills, and his \"bonus\" isn't useful at all--since he picked the goddess, Aqua, herself. How are the two of them supposed to defeat the evil Devil King and live happily ever after? Well, for them, it probably starts with day laboring rather than adventuring. And it's only going to get more disappointing from there!\n\n(Source: Crunchyroll)",
