			"native": "東京卍リベンジャーズ",
			"synopsis": "Hanagaki Takemichi was once a low-life punk, but after biting off more than he could chew with a gang in middle school, he ran away from his old life. Now that he’s an adult, the gang that once terrorized him has grown into the largest gang in Tokyo, and they’ve started killing people–including his old girlfriend! After learning this news, a mysterious force on a train platform shoves Takemichi right in front of an approaching train. As his life flashes before his eyes, he blinks to find himself transported back to middle school, before he fled from the gang! Now he has the chance to right what went wrong all those years ago. Can he save his girlfriend’s life in the future–and what else might he change if he’s rewriting the past?\n\n(Source: Seven Seas Entertainment)\n\nNotes:\n\n- Winner of the Shounen Manga category of the 44th annual Kodansha Manga Awards.\n\n- Includes one extra chapter.",
