			"kind": "MANGA",
			"title": "Uzumaki: Spiral into Horror",
			"romaji": "Uzumaki",
			"native": "うずまき",
			"synopsis": "Kurozu-cho, a small fogbound town on the coast of Japan, is cursed. According to Shuichi Saito, the withdrawn boyfriend of teenager Kirie Goshima, their town is haunted not by a person or being but by a pattern: uzumaki, the spiral, the hypnotic secret shape of the world. It manifests itself in small ways: seashells, ferns, whirlpools in water, whirlwinds in air. And in large ways: the spiral marks on people's bodies, the insane obsessions of Shuichi's father, the voice from the cochlea in your inner ear. As the madness spreads, the inhabitants of Kurouzu-cho are pulled ever deeper, as if into a whirlpool from which there is no return...\n\n(Source: VIZ Media)\n\nNotes:\n\n- Includes the extra chapter \"Uzumaki Tokubetsu-hen: Ginga\", which was included in editions later released.\n\n- Chosen by the American Library Association (ALA) as one of the Top Ten Great Graphic Novels for Teens 2009. (Vol.",
