			"synopsis": "Kusunoki used to believe he was destined for great things. But now, approaching the age of twenty, he’s a completely mediocre college student with no motivation, no dreams, and no money. After learning he can sell his remaining years, he chooses to divest himself of all but his last three months. Spending this remaining time with his monitor, Miyagi, has Kusunoki truly destroyed his final chance to find happiness…or has he somehow found it?\n\n(Source: Yen Press)\n\nNote: Includes two extra chapters.",
